           VerifyOffsetRequired(verifier, VT_BODY_NAME) &&
           verifier.VerifyString(BODY_NAME()) &&
           VerifyField<int32_t>(verifier, VT_BODY_NAIF_ID, 4) &&
           VerifyField<uint32_t>(verifier, VT_NORAD_CAT_ID, 4) &&
           VerifyOffset(verifier, VT_OBJECT_ID) &&
           verifier.VerifyString(OBJECT_ID()) &&
           VerifyOffsetRequired(verifier, VT_WINDOW_START) &&
           verifier.VerifyString(WINDOW_START()) &&
           VerifyOffsetRequired(verifier, VT_WINDOW_END) &&
           verifier.VerifyString(WINDOW_END()) &&
           VerifyOffset(verifier, VT_RBF_RECORD_IDS) &&
           verifier.VerifyVector(RBF_RECORD_IDS()) &&
           verifier.VerifyVectorOfStrings(RBF_RECORD_IDS()) &&
           VerifyOffset(verifier, VT_SPACE_WEATHER_REFS) &&
           verifier.VerifyVector(SPACE_WEATHER_REFS()) &&
           verifier.VerifyVectorOfStrings(SPACE_WEATHER_REFS()) &&
           VerifyOffset(verifier, VT_SHIELDING) &&
           verifier.VerifyTable(SHIELDING()) &&
           VerifyField<double>(verifier, VT_INSTANT_DOSE_RATE_MSV_H, 8) &&
           VerifyField<double>(verifier, VT_ORBIT_AVG_DOSE_RATE_MSV_H, 8) &&
           VerifyField<double>(verifier, VT_MISSION_DOSE_MSV, 8) &&
           VerifyField<double>(verifier, VT_TID_KRAD_SI, 8) &&
           VerifyField<int8_t>(verifier, VT_EFFECT_SEVERITY, 1) &&
           VerifyOffset(verifier, VT_PASS_DOSES) &&
           verifier.VerifyVector(PASS_DOSES()) &&
           verifier.VerifyVectorOfTables(PASS_DOSES()) &&
           VerifyOffset(verifier, VT_SHIELDING_CURVE) &&
           verifier.VerifyVector(SHIELDING_CURVE()) &&
           verifier.VerifyVectorOfTables(SHIELDING_CURVE()) &&
           VerifyOffset(verifier, VT_ELECTRONICS) &&
           verifier.VerifyTable(ELECTRONICS()) &&
           VerifyOffset(verifier, VT_CREW) &&
           verifier.VerifyTable(CREW()) &&
           VerifyOffset(verifier, VT_SEP_EFFECTS) &&
           verifier.VerifyVector(SEP_EFFECTS()) &&
           verifier.VerifyVectorOfTables(SEP_EFFECTS()) &&
           VerifyOffsetRequired(verifier, VT_PROVENANCE) &&
           verifier.VerifyTable(PROVENANCE()) &&
           verifier.EndTable();
